	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, t int
	fmt.Fscan(in, &n, &t)

	// dp[pos][prevY][humps][dips][lastDir]
	// lastDir: -1 = none (start), 0 = down, 1 = up
	// We'll use a map-based DP to avoid huge zero arrays.
	// But n<=20, y in [1..4], t<=10, so arrays are fine.

	// dp[pos][prevY][humps][dips][lastDir]
	var dp [21][5][11][11][3]int64

	// Initialize: position 1, choose y1 in [1..4], no previous direction
	for y := 1; y <= 4; y++ {
		dp[1][y][0][0][0]++ // lastDir 0 means "none" here
	}

	for pos := 1; pos < n; pos++ {
		for prevY := 1; prevY <= 4; prevY++ {
			for humps := 0; humps <= t; humps++ {
				for dips := 0; dips <= t-1; dips++ {
					for lastDir := 0; lastDir <= 2; lastDir++ {
						cur := dp[pos][prevY][humps][dips][lastDir]
						if cur == 0 {
							continue
						}
						for nextY := 1; nextY <= 4; nextY++ {
							if nextY == prevY {
								continue // no horizontal segments
							}
							newDir := 0
							if nextY > prevY {
								newDir = 1
							} else {
								newDir = 2
							}

							newHumps := humps
							newDips := dips

							if lastDir != 0 { // not the first segment
								if lastDir == 1 && newDir == 2 {
									// was going up, now going down -> peak
									newHumps++
								} else if lastDir == 2 && newDir == 1 {
									// was going down, now going up -> valley
									newDips++
								}
							}

							if newHumps > t || newDips > t-1 {
								continue
							}

							dp[pos+1][nextY][newHumps][newDips][newDir] += cur
						}
					}
				}
			}
		}
	}

	var result int64
	for y := 1; y <= 4; y++ {
		for lastDir := 1; lastDir <= 2; lastDir++ {
			result += dp[n][y][t][t-1][lastDir]
		}
	}

	fmt.Println(result)
}
