func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, t int
	fmt.Fscan(reader, &n, &t)

	// dp[i][last][prev][humps][valleys]
	// i: current position (1-based)
	// last: y[i]
	// prev: y[i-1]
	// humps: count of peaks so far
	// valleys: count of valleys so far
	// We'll use a map or 5D array. Given constraints, a 5D array is feasible.
	// n up to 20, y in [1,4], t up to 10.
	// Dimensions: [n+1][5][5][t+1][t]
	// But t can be up to 10, and valleys = humps - 1 or humps.
	// Actually, the problem requires exactly t humps and t-1 valleys.
	// So we track humps and valleys separately, but they are related.
	// Let's track humps and valleys up to t and t-1 respectively.

	// To simplify, we'll track humps (up to t) and valleys (up to t-1).
	// If humps exceed t or valleys exceed t-1, we can prune.

	// Initialize DP
	// dp[i][last][prev][humps][valleys]
	maxHumps := t
	maxValleys := t - 1
	if maxValleys < 0 {
		maxValleys = 0
	}

	// Using a 5D slice
	dp := make([][][][][]int, n+1)
	for i := range dp {
		dp[i] = make([][][][]int, 5)
		for last := range dp[i] {
			dp[i][last] = make([][][]int, 5)
			for prev := range dp[i][last] {
				dp[i][last][prev] = make([][]int, maxHumps+1)
				for h := range dp[i][last][prev] {
					dp[i][last][prev][h] = make([]int, maxValleys+1)
				}
			}
		}
	}

	// Base case: i=2 (first two points)
	// x1=1, x2=2. y1 and y2 can be any from 1 to 4, but y2 != y1 (no horizontal segments)
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 != y2 {
				dp[2][y2][y1][0][0] = 1
			}
		}
	}

	// Fill DP for i from 3 to n
	for i := 3; i <= n; i++ {
		for last := 1; last <= 4; last++ {
			for prev := 1; prev <= 4; prev++ {
				if prev == last {
					continue // no horizontal segments
				}
				for h := 0; h <= maxHumps; h++ {
					for v := 0; v <= maxValleys; v++ {
						if dp[i-1][prev][last][h][v] == 0 {
							continue
						}
						// Try all possible next values
						for next := 1; next <= 4; next++ {
							if next == last {
								continue // no horizontal segments
							}
							newH := h
							newV := v
							// Check if prev is a peak or valley
							// prev is at position i-1, last is at i, next is at i+1
							// Wait, we need to check the point at position i-1 (which is 'prev' in dp[i-1][prev][last])
							// Actually, in dp[i-1][prev][last], prev is y[i-2], last is y[i-1]
							// When we add 'next' as y[i], we check if y[i-1] (last) is a peak or valley
							// Peak: y[i-2] < y[i-1] > y[i] => prev < last > next
							// Valley: y[i-2] > y[i-1] < y[i] => prev > last < next
							if prev < last && last > next {
								newH = h + 1
							} else if prev > last && last < next {
								newV = v + 1
							}
							if newH > maxHumps || newV > maxValleys {
								continue
							}
							dp[i][next][last][newH][newV] += dp[i-1][prev][last][h][v]
						}
					}
				}
			}
		}
	}

	// Sum all dp[n][last][prev][t][t-1]
	result := 0
	for last := 1; last <= 4; last++ {
		for prev := 1; prev <= 4; prev++ {
			if last == prev {
				continue
			}
			result += dp[n][last][prev][t][t-1]
		}
	}

	fmt.Println(result)
}
