import (
	"bufio"
	"fmt"
	"os"
)

var n, t int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &t)
	fmt.Println(count(1, 0, 0, 0, 0))
}

func count(pos, prevY, humps, valleys, lastDir int) int {
	if pos == n {
		if humps == t && valleys == t-1 {
			return 1
		}
		return 0
	}
	total := 0
	for y := 1; y <= 4; y++ {
		if y == prevY {
			continue
		}
		dir := 0
		if y > prevY {
			dir = 1
		} else {
			dir = -1
		}
		newHumps := humps
		newValleys := valleys
		if pos > 1 {
			if lastDir == 1 && dir == -1 {
				newHumps++
			} else if lastDir == -1 && dir == 1 {
				newValleys++
			}
		}
		if newHumps > t || newValleys > t-1 {
			continue
		}
		total += count(pos+1, y, newHumps, newValleys, dir)
	}
	return total
}
