package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, t int
	fmt.Fscan(in, &n, &t)

	// dp[pos][prev][curr][humps][valleys]
	// humps = count of peaks so far, valleys = count of valleys so far
	// We'll use a map-based DP to avoid huge memory.
	// But n<=20, y in [1..4], so state is manageable with arrays.

	// Let's define dp as a map keyed by (prev, curr, humps, valleys) -> count
	// at each position.

	// Initialize: position 1 has y1, position 2 has y2.
	// We start building from position 2 (index 1 in 0-based), tracking prev=y1, curr=y2.

	// dp[prev][curr][humps][valleys] = count
	// humps and valleys up to current position.

	// Since n can be up to 20 and t up to 10, and y in 1..4,
	// we can use a 4D array: dp[prev][curr][humps][valleys]
	// prev: 1..4, curr: 1..4, humps: 0..t, valleys: 0..t-1

	// But we need to be careful: humps can be at most t, valleys at most t-1.

	// Let's use a map for flexibility.

	type State struct {
		prev, curr, humps, valleys int
	}

	dp := make(map[State]int)

	// Initialize for position 2 (we have y1 and y2)
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y2 == y1 {
				continue // no segment parallel to Ox
			}
			dp[State{y1, y2, 0, 0}]++
		}
	}

	// Iterate from position 3 to n
	for pos := 3; pos <= n; pos++ {
		nextDp := make(map[State]int)
		for state, count := range dp {
			prev := state.prev
			curr := state.curr
			humps := state.humps
