	}
	// Fill DP
	for pos := 1; pos < n; pos++ {
		for prevY := 1; prevY <= 4; prevY++ {
			for humps := 0; humps <= maxT; humps++ {
				for valleys := 0; valleys <= maxV; valleys++ {
					for lastDir := 0; lastDir <= 2; lastDir++ {
