								// lastDir: 1 = up (prevY was increasing), 2 = down (prevY was decreasing)
								// If lastDir was up (1) and newDir is down (2), then prevY is a peak
								if lastDir == 1 && newDir == 2 {
									newHumps++
								} else if lastDir == 2 && newDir == 1 {
