func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &t)
	fmt.Println(solve())
}

func solve() int {
	for i := 0; i < 21; i++ {
		for j := 0; j < 5; j++ {
			for k := 0; k < 5; k++ {
				for l := 0; l < 11; l++ {
					for m := 0; m < 11; m++ {
						dp[i][j][k][l][m] = -1
					}
				}
			}
		}
	}
	res := 0
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 == y2 {
				continue
			}
			res += dfs(2, y1, y2, 0, 0)
		}
	}
	return res
}

func dfs(pos, prev, curr, humps, valleys int) int {
	if pos == n {
		if humps == t && valleys == t-1 {
			return 1
		}
		return 0
	}
	if humps > t || valleys > t-1 {
		return 0
	}
	key := dp[pos][prev][curr][humps][valleys]
	if key != -1 {
		return key
	}
	res := 0
	for next := 1; next <= 4; next++ {
		if next == curr {
			continue
		}
		newHumps := humps
		newValleys := valleys
		if curr > prev && curr > next {
			newHumps++
		}
		if curr < prev && curr < next {
			newValleys++
		}
		res += dfs(pos+1, curr, next, newHumps, newValleys)
	}
	dp[pos][prev][curr][humps][valleys] = res
	return res
