	// Actually, let's think of it as: at position 1, we pick y1, lastDir = none
	// Then at position 2, we pick y2, determine direction
	// Let's restructure: dp[pos][y][humps][dips][dir]
	// pos from 1 to n, y from 1 to 4

	// Re-initialize properly with 5D
	dp2 := make([][][][][]int, n+1)
	for i := range dp2 {
		dp2[i] = make([][][][]int, 5)
