				for l := range dp2[i][j][k] {
					dp2[i][j][k][l] = make([]int, 3)
				}
			}
		}
	}

	// Position 1: choose y1, humps=0, dips=0, dir=0 (none)
	for y := 1; y <= 4; y++ {
		dp2[1][y][0][0][0] = 1
	}

	for pos := 1; pos < n; pos++ {
		for y := 1; y <= 4; y++ {
			for humps := 0; humps <= t; humps++ {
