package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	var n, t int
	fmt.Fscan(r, &n, &t)

	// dp[pos][prev][humps][dips][prevDir]
	// prevDir: 0 = none (start), 1 = up, 2 = down
	// humps: number of peaks so far
	// dips: number of valleys so far
	// We'll use a map-based memoization or iterative DP.

	// Since n <= 20, t <= 10, and yi in [1,4], we can do DP over positions.
	// State: position, previous y, previous direction, count of humps, count of dips.
	// But humps and dips can be up to t and t-1 respectively, so we need to track them.

	// Let's use a 5-dimensional DP array.
	// dp[pos][prevY][prevDir][humps][dips]
	// pos: 1..n
	// prevY: 1..4
	// prevDir: 0 (none), 1 (up), 2 (down)
	// humps: 0..t
	// dips: 0..t-1

	// Initialize DP
	// We'll use a map for sparse representation, or a 5D array.
	// Given constraints, let's use a 5D array.

	maxHumps := t
	maxDips := t - 1

	// dp[pos][prevY][prevDir][humps][dips]
	dp := [21][5][3][11][11]int{}

	// Base case: position 1, no previous direction
	// At position 1, we just set the first y value
	for y := 1; y <= 4; y++ {
		dp[1][y][0][0][0] = 1
	}

	// Fill DP
	for pos := 1; pos < n; pos++ {
		for prevY := 1; prevY <= 4; prevY++ {
			for prevDir := 0; prevDir <= 2; prevDir++ {
				for humps := 0; humps <= maxHumps; humps++ {
					for dips := 0; dips <= maxDips; dips++ {
						count := dp[pos][prevY][prevDir][humps][dips]
						if count == 0 {
							continue
						}

						// Try all possible next y values
						for nextY := 1; nextY <= 4; nextY++ {
							if nextY == prevY {
								continue // No horizontal segments
							}

							var currDir int
							if nextY > prevY {
								currDir = 1 // up
							} else {
								currDir = 2 // down
							}

							newHumps := humps
							newDips := dips

							// Check if we form a peak or valley at position pos
							// A peak is at position pos if prevDir was up and currDir is down
							// A valley is at position pos if prevDir was down and currDir is up
							if pos >= 2 {
								if prevDir == 1 && currDir == 2 {
									// Peak at position pos
									newHumps++
								} else if prevDir == 2 && currDir == 1 {
									// Valley at position pos
									newDips++
								}
							}

							// Check bounds
							if newHumps > maxHumps || newDips > maxDips {
								continue
							}

							dp[pos+1][nextY][currDir][newHumps][newDips] += count
						}
					}
				}
			}
		}
	}

	// Sum up all states at position n with exactly t humps and t-1 dips
	result := 0
	for prevY := 1; prevY <= 4; prevY++ {
		for prevDir := 1; prevDir <= 2; prevDir++ {
			result += dp[n][prevY][prevDir][t][t-1]
		}
	}

	fmt.Println(result)
}
